import json
R,C=20,13
g=[[4]*C for _ in range(R)]
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(12,11),(17,4),(17,8)]
for r,c in markers:g[r][c]=1
# original 3x3 motif centered at (12,7); 4 is transparent background
motif=[[4,5,5],[8,5,8],[8,5,0]]
for dr in range(-1,2):
 for dc in range(-1,2):
  if motif[dr+1][dc+1]!=4:g[12+dr][7+dc]=motif[dr+1][dc+1]
# stamp motif around each 1 marker, with its center (5) aligned to marker
for r,c in markers:
 for dr in range(-1,2):
  for dc in range(-1,2):
   v=motif[dr+1][dc+1]
   if v!=4:
    rr,cc=r+dr,c+dc
    if 0<=rr<R and 0<=cc<C:g[rr][cc]=v
print(json.dumps(g,separators=(',',':')))
